// AutoED-ERP data model. One compact definition per table.
// Column spec: "key[:type][!][=default][{opt|opt}]" or "key>ref_table[!]"  (types: text int numeric bool date time ts jsonb uuid)
// Options: cap (permission capability), branch/year (adds branch_id/year_id), readAll (every org member may read),
// student (family may read rows for their children), own (creator column), staffOwn (staff may read own rows),
// audit (false | 'ud'), custom (adds custom jsonb for tenant-defined fields), sql (extra policies).
const famPolicy = (t, name, cmd, expr) =>
  cmd === 'insert'
    ? `create policy ${t}_${name} on public.${t} for insert to authenticated with check (${expr});`
    : `create policy ${t}_${name} on public.${t} for ${cmd} to authenticated using (${expr});`;
const MINE = `student_id = any((select app.my_students())::uuid[])`;
const ORG = `org_id = (select app.org_id())`;

